def chat_completion(model, messages, api_key_id=None, upstream_api_key_id=None, temperature=None, top_p=None, max_tokens=None, stop=None, stream=None, seed=None, response_format=None, metadata=None, **_extra):
    import json, os, datetime, time, hashlib, base64, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0075000" if __import__("os").path.isdir("./environment_mix/0075000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "chat_completion"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_request_log():
        try:
            os.makedirs(_DB, exist_ok=True)
        except Exception:
            return False
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            try:
                _save("request_logs.json", [])
            except Exception:
                return False
        return True

    def _log(status, credential_id=None, error_code=None):
        if not _ensure_request_log():
            return
        logs = _load("request_logs.json")
        logs.append({
            "id": "req_" + base64.urlsafe_b64encode(os.urandom(9)).decode("ascii").rstrip("="),
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now()
        })
        _save("request_logs.json", logs)

    def _parse_ts(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _rate_limit_check_and_bump(client_key_row):
        if client_key_row is None:
            return None
        logs = _load("request_logs.json") if os.path.exists(os.path.join(_DB, "request_logs.json")) else []
        now = datetime.datetime.utcnow()
        window_start = now - datetime.timedelta(seconds=60)
        count = 0
        for r in reversed(logs[-5000:]):
            if r.get("credential_id") != client_key_row.get("id"):
                continue
            ts = _parse_ts(r.get("timestamp"))
            if ts is None:
                continue
            if ts < window_start:
                continue
            if r.get("endpoint") == endpoint:
                count += 1
        rpm = client_key_row.get("rate_limit_rpm")
        if isinstance(rpm, int) and rpm >= 1 and count >= rpm:
            return _err("RATE_LIMIT", "Rate limit exceeded.", limit_rpm=rpm)
        return None

    def _resolve_model(identifier, models, aliases):
        # Return model row or None; alias must be active
        for m in models:
            if m.get("model_id") == identifier:
                return m
        for a in aliases:
            if a.get("alias") == identifier and a.get("status") == "active":
                mid = a.get("model_id")
                for m in models:
                    if m.get("id") == mid:
                        return m
        return None

    def _maybe_enqueue_on_demand_sync():
        # Non-blocking. If newest succeeded finished_at older than TTL, enqueue queued job.
        TTL_SECONDS = 6 * 60 * 60
        jobs = _load("model_catalog_sync_jobs.json")
        newest = None
        for j in jobs:
            if j.get("status") != "succeeded":
                continue
            ts = _parse_ts(j.get("finished_at"))
            if ts is None:
                continue
            if newest is None or ts > newest:
                newest = ts
        now = datetime.datetime.utcnow()
        stale = (newest is None) or ((now - newest).total_seconds() > TTL_SECONDS)
        if not stale:
            return
        # idempotency: do not enqueue if a queued/running on_demand exists
        for j in jobs:
            if j.get("trigger") == "on_demand" and j.get("status") in ("queued", "running"):
                return
        jid = "sync_" + base64.urlsafe_b64encode(os.urandom(9)).decode("ascii").rstrip("=")
        ts = _now()
        jobs.append({
            "id": jid,
            "trigger": "on_demand",
            "status": "queued",
            "started_at": None,
            "finished_at": None,
            "models_upserted": 0,
            "models_disabled": 0,
            "error_message": None,
            "created_at": ts,
            "updated_at": ts
        })
        _save("model_catalog_sync_jobs.json", jobs)

    # ---------- Validate input ----------
    if not isinstance(model, str) or not model.strip():
        _log("error", credential_id=api_key_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "model must be a non-empty string.")
    if not isinstance(messages, list) or len(messages) == 0:
        _log("error", credential_id=api_key_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "messages must be a non-empty array.")
    allowed_roles = {"system", "user", "assistant", "tool"}
    for i, m in enumerate(messages):
        if not isinstance(m, dict):
            _log("error", credential_id=api_key_id, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"messages[{i}] must be an object.")
        if m.get("role") not in allowed_roles:
            _log("error", credential_id=api_key_id, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"messages[{i}].role must be one of {sorted(list(allowed_roles))}.")
        if "content" not in m:
            _log("error", credential_id=api_key_id, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"messages[{i}].content is required.")
        c = m.get("content")
        if not (isinstance(c, str) or isinstance(c, dict) or isinstance(c, list)):
            _log("error", credential_id=api_key_id, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"messages[{i}].content must be string, object, or array.")

    if temperature is not None and not isinstance(temperature, (int, float)):
        _log("error", credential_id=api_key_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "temperature must be a number.")
    if top_p is not None and not isinstance(top_p, (int, float)):
        _log("error", credential_id=api_key_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "top_p must be a number.")
    if max_tokens is not None and not isinstance(max_tokens, int):
        _log("error", credential_id=api_key_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "max_tokens must be an integer.")
    if stop is not None and not (isinstance(stop, str) or (isinstance(stop, list) and all(isinstance(x, str) for x in stop))):
        _log("error", credential_id=api_key_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "stop must be a string or array of strings.")
    if stream is not None and not isinstance(stream, bool):
        _log("error", credential_id=api_key_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "stream must be a boolean.")
    if seed is not None and not isinstance(seed, int):
        _log("error", credential_id=api_key_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "seed must be an integer.")
    if response_format is not None and not isinstance(response_format, dict):
        _log("error", credential_id=api_key_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "response_format must be an object.")
    if metadata is not None and not isinstance(metadata, dict):
        _log("error", credential_id=api_key_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "metadata must be an object.")

    key_id_pat = re.compile(r"^orak_[0-9A-Z]{3,}$")
    if api_key_id is not None and (not isinstance(api_key_id, str) or not key_id_pat.match(api_key_id)):
        _log("error", credential_id=api_key_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "api_key_id is invalid.")
    if upstream_api_key_id is not None and (not isinstance(upstream_api_key_id, str) or not key_id_pat.match(upstream_api_key_id)):
        _log("error", credential_id=api_key_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "upstream_api_key_id is invalid.")

    # ---------- Resolve authentication context ----------
    api_keys = _load("api_keys.json")
    client_key = None
    upstream_key = None

    if api_key_id is not None:
        for k in api_keys:
            if k.get("id") == api_key_id and k.get("key_type") == "client":
                client_key = k
                break
        if client_key is None:
            _log("error", credential_id=api_key_id, error_code="UNAUTHORIZED")
            return _err("UNAUTHORIZED", "Unknown client api key.")
        if client_key.get("status") != "active":
            _log("error", credential_id=client_key.get("id"), error_code="UNAUTHORIZED")
            return _err("UNAUTHORIZED", "Client api key is not active.")
    # upstream selection
    if upstream_api_key_id is not None:
        for k in api_keys:
            if k.get("id") == upstream_api_key_id and k.get("key_type") == "upstream":
                upstream_key = k
                break
        if upstream_key is None:
            _log("error", credential_id=(client_key or {}).get("id") or upstream_api_key_id, error_code="UNAUTHORIZED")
            return _err("UNAUTHORIZED", "Unknown upstream api key.")
        if upstream_key.get("status") != "active":
            _log("error", credential_id=(client_key or {}).get("id") or upstream_key.get("id"), error_code="UNAUTHORIZED")
            return _err("UNAUTHORIZED", "Upstream api key is not active.")
    else:
        # pick any active upstream key
        for k in api_keys:
            if k.get("key_type") == "upstream" and k.get("status") == "active":
                upstream_key = k
                break
        if upstream_key is None:
            _log("error", credential_id=(client_key or {}).get("id"), error_code="UNAUTHORIZED")
            return _err("UNAUTHORIZED", "No upstream credential available.")

    # Ensure request log exists before rate checks (since checks read it)
    _ensure_request_log()

    rl_err = _rate_limit_check_and_bump(client_key)
    if rl_err is not None:
        _log("error", credential_id=client_key.get("id") if client_key else None, error_code="RATE_LIMIT")
        return rl_err

    # ---------- Resolve model ----------
    _maybe_enqueue_on_demand_sync()
    models = _load("models.json")
    aliases = _load("model_aliases.json")
    resolved = _resolve_model(model, models, aliases)

    # ---------- Create chat completion row queued ----------
    completions = _load("chat_completions.json")
    cid = "cc_" + base64.urlsafe_b64encode(os.urandom(9)).decode("ascii").rstrip("=")
    ts = _now()
    request_payload = {
        "model": model,
        "messages": messages
    }
    if temperature is not None: request_payload["temperature"] = temperature
    if top_p is not None: request_payload["top_p"] = top_p
    if max_tokens is not None: request_payload["max_tokens"] = max_tokens
    if stop is not None: request_payload["stop"] = stop
    if stream is not None: request_payload["stream"] = stream
    if seed is not None: request_payload["seed"] = seed
    if response_format is not None: request_payload["response_format"] = response_format
    if metadata is not None: request_payload["metadata"] = metadata

    row = {
        "id": cid,
        "client_api_key_id": client_key.get("id") if client_key else None,
        "upstream_api_key_id": upstream_key.get("id") if upstream_key else None,
        "requested_model": model,
        "resolved_model_id": resolved.get("id") if resolved else None,
        "request_payload": request_payload,
        "response_payload": None,
        "status": "queued",
        "error_code": None,
        "error_message": None,
        "prompt_tokens": None,
        "completion_tokens": None,
        "total_tokens": None,
        "cost_usd": None,
        "latency_ms": None,
        "created_at": ts,
        "updated_at": ts
    }
    completions.append(row)
    _save("chat_completions.json", completions)

    # Update last_used_at for keys (best effort)
    for k in api_keys:
        if client_key and k.get("id") == client_key.get("id"):
            k["last_used_at"] = ts
            k["updated_at"] = ts
        if upstream_key and k.get("id") == upstream_key.get("id"):
            k["last_used_at"] = ts
            k["updated_at"] = ts
    _save("api_keys.json", api_keys)

    # ---------- If invalid model: fail without upstream ----------
    if resolved is None or resolved.get("status") not in ("active", "deprecated"):
        # transition queued -> failed
        for r in completions:
            if r.get("id") == cid:
                r["status"] = "failed"
                r["error_code"] = "invalid_model"
                r["error_message"] = "Requested model identifier is not valid."
                r["updated_at"] = _now()
                r["latency_ms"] = int((time.time() - t0) * 1000)
                break
        _save("chat_completions.json", completions)
        _log("ok", credential_id=client_key.get("id") if client_key else None, error_code=None)
        return {
            "id": cid,
            "object": "chat.completion",
            "created": int(time.time()),
            "model": model,
            "choices": [],
            "error": {"code": "invalid_model", "message": "Requested model identifier is not valid."}
        }

    # ---------- Pre-spend cap check (estimate) ----------
    def _estimate_tokens_from_messages(msgs):
        # rough heuristic to avoid external tokenizers
        chars = 0
        for mm in msgs:
            c = mm.get("content")
            if isinstance(c, str):
                chars += len(c)
            elif isinstance(c, dict):
                try:
                    chars += len(json.dumps(c, ensure_ascii=False))
                except Exception:
                    chars += 0
            elif isinstance(c, list):
                try:
                    chars += len(json.dumps(c, ensure_ascii=False))
                except Exception:
                    chars += 0
        # approx 4 chars/token
        return max(1, chars // 4)

    def _estimate_cost_usd(model_row, prompt_toks, completion_toks):
        pp = model_row.get("pricing_prompt_usd_per_1k")
        pc = model_row.get("pricing_completion_usd_per_1k")
        if not isinstance(pp, (int, float)) or not isinstance(pc, (int, float)):
            return None
        return (prompt_toks / 1000.0) * float(pp) + (completion_toks / 1000.0) * float(pc)

    estimated_cost = None
    if client_key and client_key.get("monthly_spend_cap_usd") is not None:
        prompt_est = _estimate_tokens_from_messages(messages)
        completion_est = int(max_tokens) if isinstance(max_tokens, int) and max_tokens > 0 else 256
        estimated_cost = _estimate_cost_usd(resolved, prompt_est, completion_est)
        if estimated_cost is not None:
            used = client_key.get("monthly_spend_used_usd")
            cap = client_key.get("monthly_spend_cap_usd")
            if isinstance(used, (int, float)) and isinstance(cap, (int, float)) and (float(used) + float(estimated_cost) > float(cap) + 1e-9):
                # fail request (queued -> failed)
                completions = _load("chat_completions.json")
                for r in completions:
                    if r.get("id") == cid:
                        r["status"] = "failed"
                        r["error_code"] = "quota_exceeded"
                        r["error_message"] = "Monthly spend cap would be exceeded."
                        r["updated_at"] = _now()
                        r["latency_ms"] = int((time.time() - t0) * 1000)
                        break
                _save("chat_completions.json", completions)
                _log("error", credential_id=client_key.get("id"), error_code="QUOTA_EXCEEDED")
                return _err("QUOTA_EXCEEDED", "Monthly spend cap would be exceeded.", estimated_cost_usd=estimated_cost)

    # ---------- Transition queued -> running ----------
    completions = _load("chat_completions.json")
    found = False
    for r in completions:
        if r.get("id") == cid:
            found = True
            if r.get("status") != "queued":
                _log("error", credential_id=client_key.get("id") if client_key else None, error_code="INVALID_TRANSITION")
                return _err("INVALID_TRANSITION", "Completion is not in queued state.")
            r["status"] = "running"
            r["updated_at"] = _now()
            break
    if not found:
        _log("error", credential_id=client_key.get("id") if client_key else None, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Completion record not found.")
    _save("chat_completions.json", completions)

    # ---------- "Call upstream" (offline deterministic stub) ----------
    # Real backend would call OpenRouter. Here we produce a stable, model-dependent response and usage.
    # If stream=True, return a stream-like envelope with chunks.
    def _stable_hash(s):
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    # craft assistant content
    last_user = None
    for mm in reversed(messages):
        if mm.get("role") == "user":
            last_user = mm.get("content")
            break
    if isinstance(last_user, (dict, list)):
        try:
            last_user_txt = json.dumps(last_user, ensure_ascii=False)
        except Exception:
            last_user_txt = ""
    else:
        last_user_txt = last_user if isinstance(last_user, str) else ""
    seed_material = f"{cid}|{resolved.get('model_id')}|{last_user_txt[:500]}"
    h = _stable_hash(seed_material)
    assistant_text = "Offline OpenRouter mirror response. " + (last_user_txt[:240] if last_user_txt else f"request_hash={h[:16]}")
    if isinstance(max_tokens, int) and max_tokens > 0:
        assistant_text = assistant_text[: max(1, min(len(assistant_text), max_tokens * 4))]

    prompt_tokens = _estimate_tokens_from_messages(messages)
    completion_tokens = max(1, len(assistant_text) // 4)
    total_tokens = prompt_tokens + completion_tokens
    computed_cost = _estimate_cost_usd(resolved, prompt_tokens, completion_tokens)

    response_payload = {
        "id": "orcmpl_" + h[:20],
        "object": "chat.completion",
        "created": int(time.time()),
        "model": resolved.get("model_id"),
        "choices": [{
            "index": 0,
            "message": {"role": "assistant", "content": assistant_text},
            "finish_reason": "stop"
        }],
        "usage": {
            "prompt_tokens": prompt_tokens,
            "completion_tokens": completion_tokens,
            "total_tokens": total_tokens
        }
    }
    if computed_cost is not None:
        response_payload["cost_usd"] = computed_cost

    # ---------- Transition running -> succeeded and persist usage/cost ----------
    completions = _load("chat_completions.json")
    updated = False
    for r in completions:
        if r.get("id") == cid:
            if r.get("status") != "running":
                _log("error", credential_id=client_key.get("id") if client_key else None, error_code="INVALID_TRANSITION")
                return _err("INVALID_TRANSITION", "Completion is not in running state.")
            r["status"] = "succeeded"
            r["response_payload"] = response_payload
            r["prompt_tokens"] = prompt_tokens
            r["completion_tokens"] = completion_tokens
            r["total_tokens"] = total_tokens
            r["cost_usd"] = computed_cost
            r["latency_ms"] = int((time.time() - t0) * 1000)
            r["updated_at"] = _now()
            updated = True
            break
    if not updated:
        _log("error", credential_id=client_key.get("id") if client_key else None, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Completion record not found.")
    _save("chat_completions.json", completions)

    # Increment monthly spend used atomically (load-modify-save)
    if client_key and computed_cost is not None:
        api_keys = _load("api_keys.json")
        for k in api_keys:
            if k.get("id") == client_key.get("id"):
                used = k.get("monthly_spend_used_usd")
                if not isinstance(used, (int, float)):
                    used = 0.0
                k["monthly_spend_used_usd"] = float(used) + float(computed_cost)
                k["updated_at"] = _now()
                break
        _save("api_keys.json", api_keys)

    _log("ok", credential_id=client_key.get("id") if client_key else None)

    if stream:
        # Return pseudo-stream chunks while still being a normal tool result
        text = assistant_text
        chunks = []
        step = max(1, min(48, len(text) // 6 if len(text) else 1))
        idx = 0
        while idx < len(text):
            part = text[idx:idx + step]
            idx += step
            chunks.append({
                "id": response_payload["id"],
                "object": "chat.completion.chunk",
                "created": response_payload["created"],
                "model": response_payload["model"],
                "choices": [{"index": 0, "delta": {"content": part}, "finish_reason": None}]
            })
        chunks.append({
            "id": response_payload["id"],
            "object": "chat.completion.chunk",
            "created": response_payload["created"],
            "model": response_payload["model"],
            "choices": [{"index": 0, "delta": {}, "finish_reason": "stop"}]
        })
        return {
            "completion_id": cid,
            "stream": True,
            "chunks": chunks,
            "final_response": response_payload
        }

    return {
        "completion_id": cid,
        "stream": False,
        "response": response_payload
    }

def search_models(query=None, provider=None, status=None, min_context_length=None, max_context_length=None, tags=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0075000" if __import__("os").path.isdir("./environment_mix/0075000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "search_models"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_request_log():
        try:
            os.makedirs(_DB, exist_ok=True)
        except Exception:
            return False
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            try:
                _save("request_logs.json", [])
            except Exception:
                return False
        return True

    def _log(status_s, credential_id=None, error_code=None):
        if not _ensure_request_log():
            return
        logs = _load("request_logs.json")
        logs.append({
            "id": "req_" + base64.urlsafe_b64encode(os.urandom(9)).decode("ascii").rstrip("="),
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status_s,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now()
        })
        _save("request_logs.json", logs)

    def _parse_ts(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _maybe_enqueue_on_demand_sync():
        TTL_SECONDS = 6 * 60 * 60
        jobs = _load("model_catalog_sync_jobs.json")
        newest = None
        for j in jobs:
            if j.get("status") != "succeeded":
                continue
            ts = _parse_ts(j.get("finished_at"))
            if ts is None:
                continue
            if newest is None or ts > newest:
                newest = ts
        now = datetime.datetime.utcnow()
        stale = (newest is None) or ((now - newest).total_seconds() > TTL_SECONDS)
        if not stale:
            return
        for j in jobs:
            if j.get("trigger") == "on_demand" and j.get("status") in ("queued", "running"):
                return
        jid = "sync_" + base64.urlsafe_b64encode(os.urandom(9)).decode("ascii").rstrip("=")
        ts = _now()
        jobs.append({
            "id": jid,
