            _log("upsert_model_alias", "error", entity_id=None, error_code="validation_error", error_message="id must be a non-empty string when provided")
            return _err("VALIDATION_ERROR", "Parameter 'id' must be a non-empty string when provided.", field="id")

        tool_alias_types = {"friendly", "compat", "vendor", "custom"}
        if alias_type is not None:
            if not isinstance(alias_type, str) or alias_type not in tool_alias_types:
                _log("upsert_model_alias", "error", entity_id=id, error_code="validation_error", error_message="invalid alias_type")
                return _err("VALIDATION_ERROR", "Invalid 'alias_type'.", field="alias_type", allowed=sorted(tool_alias_types))

        if status is not None:
            if not isinstance(status, str) or status not in {"active", "disabled"}:
                _log("upsert_model_alias", "error", entity_id=id, error_code="validation_error", error_message="invalid status")
