            elif db_alias_type == "custom":
                db_alias_type = "custom"

            row = {
                "id": new_id,
                "model_id": target_model_pk,
                "alias": alias,
                "alias_type": db_alias_type,
                "status": status or "active",
                "created_at": now,
                "updated_at": now,
            }
            aliases.append(row)
            _save("model_aliases.json", aliases)
            _log("upsert_model_alias", "ok", entity_id=new_id, credential_id=credential.get("id"))
            return {"data": row}

        # Update existing
        idx = next((i for i, a in enumerate(aliases) if isinstance(a, dict) and a.get("id") == id), None)
        if idx is None:
            _log("upsert_model_alias", "error", entity_id=id, credential_id=credential.get("id"), error_code="not_found", error_message="model alias not found")
            return _err("NOT_FOUND", "Model alias not found.", id=id)

        row = aliases[idx]

        # Status transition rules for model_aliases: active <-> disabled allowed
        if status is not None:
            old = row.get("status")
            if old not in {"active", "disabled"}:
                old = "disabled" if old else "active"
            if old == "active" and status not in {"disabled", "active"}:
                return _err("INVALID_TRANSITION", "Illegal status transition.", from_status=old, to_status=status)
            if old == "disabled" and status not in {"active", "disabled"}:
                return _err("INVALID_TRANSITION", "Illegal status transition.", from_status=old, to_status=status)
            row["status"] = status

        # Update target model
        row["model_id"] = target_model_pk

        # Update alias (already uniqueness checked)
        row["alias"] = alias

        # Update alias_type (tool -> db mapping)
        if alias_type is not None:
            db_alias_type = alias_type
            if db_alias_type == "friendly":
                db_alias_type = "shortname"
            elif db_alias_type == "compat":
                db_alias_type = "legacy"
            elif db_alias_type == "vendor":
                db_alias_type = "vendor_redirect"
            elif db_alias_type == "custom":
                db_alias_type = "custom"
            row["alias_type"] = db_alias_type

        row["updated_at"] = now
        aliases[idx] = row
        _save("model_aliases.json", aliases)
        _log("upsert_model_alias", "ok", entity_id=id, credential_id=credential.get("id"))
        return {"data": row}
    except Exception as e:
        _log("upsert_model_alias", "error", entity_id=id, error_code="server_error", error_message=str(e))
        return _err("VALIDATION_ERROR", "Unexpected error.", detail=str(e))

def set_model_status(id, status, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0075000" if __import__("os").path.isdir("./environment_mix/0075000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _pick_log_file():
        for cand in ("request_logs.json", "audit_logs.json", "usage_logs.json"):
            if os.path.exists(os.path.join(_DB, cand)):
                return cand
        return "request_logs.json"

    def _log(endpoint, status_s, entity_id=None, credential_id=None, error_code=None, error_message=None):
        latency_ms = int((time.time() - t0) * 1000)
        fname = _pick_log_file()
        logs = _load(fname)
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": "req_" + os.urandom(8).hex(),
                "endpoint": endpoint,
                "status": status_s,
                "credential_id": credential_id,
                "entity_id": entity_id,
                "error_code": error_code,
                "error_message": error_message,
                "latency_ms": latency_ms,
                "timestamp": _now_iso(),
            }
        )
        _save(fname, logs)

    try:
        if not isinstance(id, str) or not id.strip():
            _log("set_model_status", "error", entity_id=None, error_code="validation_error", error_message="id must be a non-empty string")
            return _err("VALIDATION_ERROR", "Parameter 'id' must be a non-empty string.", field="id")

        allowed = {"active", "deprecated", "disabled"}
        if not isinstance(status, str) or status not in allowed:
            _log("set_model_status", "error", entity_id=id, error_code="validation_error", error_message="invalid status")
            return _err("VALIDATION_ERROR", "Invalid 'status'.", field="status", allowed=sorted(allowed))

        # Ambient auth: must have an active client key
        api_keys = _load("api_keys.json")
        api_keys = api_keys if isinstance(api_keys, list) else []
        credential = next(
            (k for k in api_keys if isinstance(k, dict) and k.get("key_type") == "client" and k.get("status") == "active"),
            None,
        )
        if credential is None:
            _log("set_model_status", "error", entity_id=id, error_code="unauthorized", error_message="no active client credential available in datastore")
            return _err("UNAUTHORIZED", "No active client credential available to authorize this request.")

        models = _load("models.json")
        models = models if isinstance(models, list) else []

        idx = next((i for i, m in enumerate(models) if isinstance(m, dict) and m.get("id") == id), None)
        if idx is None:
            _log("set_model_status", "error", entity_id=id, credential_id=credential.get("id"), error_code="not_found", error_message="model not found")
            return _err("NOT_FOUND", "Model not found.", id=id)

        row = models[idx]
        cur = row.get("status")

        transitions = {
            "active": {"deprecated", "disabled"},
            "deprecated": {"active", "disabled"},
            "disabled": {"active"},
        }
        if cur not in transitions:
            # If corrupted, treat as disabled-like and enforce strictly
            cur = "disabled"

        if status != cur:
            if status not in transitions.get(cur, set()):
                _log(
                    "set_model_status",
                    "error",
                    entity_id=id,
                    credential_id=credential.get("id"),
                    error_code="invalid_transition",
                    error_message=f"illegal transition {cur}->{status}",
                )
                return _err("INVALID_TRANSITION", "Illegal status transition.", from_status=cur, to_status=status)

            row["status"] = status
            row["updated_at"] = _now_iso()
            models[idx] = row
            _save("models.json", models)

        _log("set_model_status", "ok", entity_id=id, credential_id=credential.get("id"))
        return {"data": row}
    except Exception as e:
        _log("set_model_status", "error", entity_id=id, error_code="server_error", error_message=str(e))
        return _err("VALIDATION_ERROR", "Unexpected error.", detail=str(e))

