            return _err("VALIDATION_ERROR", "Parameter 'id' must be a non-empty string.", field="id")

        if reason is not None and not isinstance(reason, str):
            _log("cancel_chat_completion", "error", entity_id=id, error_code="validation_error", error_message="reason must be a string when provided")
            return _err("VALIDATION_ERROR", "Parameter 'reason' must be a string when provided.", field="reason")

        # Ambient auth: require any active client key exists.
        api_keys = _load("api_keys.json")
        api_keys = api_keys if isinstance(api_keys, list) else []
        credential = next(
            (k for k in api_keys if isinstance(k, dict) and k.get("key_type") == "client" and k.get("status") == "active"),
            None,
        )
        if credential is None:
            _log("cancel_chat_completion", "error", entity_id=id, error_code="unauthorized", error_message="no active client credential available in datastore")
            return _err("UNAUTHORIZED", "No active client credential available to authorize this request.")

        completions = _load("chat_completions.json")
        completions = completions if isinstance(completions, list) else []

        idx = next((i for i, c in enumerate(completions) if isinstance(c, dict) and c.get("id") == id), None)
