            _log("cancel_chat_completion", "error", entity_id=id, credential_id=credential.get("id"), error_code="not_found", error_message="chat completion not found")
            return _err("NOT_FOUND", "Chat completion not found.", id=id)

        row = completions[idx]
        cur = row.get("status")
        if cur not in {"queued", "running"}:
            _log(
                "cancel_chat_completion",
                "error",
                entity_id=id,
                credential_id=credential.get("id"),
