                "VALIDATION_ERROR",
                "Chat completion is not cancellable in its current state.",
                id=id,
                status=cur,
                allowed_statuses=["queued", "running"],
            )

        # lifecycle transition allowed: queued/running -> cancelled
        row["status"] = "cancelled"
        msg = "Cancelled by client."
